import test from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/index.ts';

const PARAMS_WITHOUT_INFLATION =
  'DIAS_MAX_DENUNCIA=30;DIAS_MAX_DENUNCIA_VIDA=365;TOLERANCIA_MORA_VIP=500;DEDUCIBLE_MINIMO=100;' +
  'PCT_DESCUENTO_DED_VIP=50;MAX_SINIESTROS_ANUAL=3;PCT_PENALIZACION_SINIEST=10;UMBRAL_RETENCION=10000;' +
  'TASA_RETENCION=2;TOPE_AUTO_APROBACION=50000;DIAS_ALERTA_FRAUDE=15;PCT_ALERTA_FRAUDE=80';

function validInput(): Record<string, string> {
  return {
    claim_amount: '5000.00',
    occurrence_date: '2026-03-01',
    report_date: '2026-03-05',
    coverage_code: 'COB1',
    policy_status: 'VIGENTE',
    policy_branch: 'AUTO',
    policy_start_date: '2026-01-01',
    policy_end_date: '2026-12-31',
    sum_insured: '100000.00',
    deductible_type: 'FIJO',
    deductible_value: '200.00',
    pending_premium: '0.00',
    customer_category: 'ESTANDAR',
    coverage_found: 'true',
    coverage_limit: '10000.00',
    coverage_percentage: '80.00',
    waiting_days: '0',
    prior_liquidated_claims_365d: '0',
    total_indemnified: '0.00',
    business_parameters: PARAMS_WITHOUT_INFLATION,
  };
}

// R-002: el legacy consulta FACTOR_INFLACION siempre; si falta, falla con ORA-20010.
test('falta FACTOR_INFLACION: ORA-20010 aunque el resto sea válido', () => {
  const out = execute(validInput());
  assert.equal(out.error_code, 'ORA-20010');
  assert.equal(out.status, '');
  assert.equal(out.net_amount, '0.00');
});
